void Solver::bump_var(int var, double coeff) {
    double bump_amount = var_inc * coeff;
    activity[var] += bump_amount;

    // Scale down if overflow risk
    if (activity[var] > 1e100) {
        for (int i = 1; i <= vars; i++) 
            activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }

    // Update heap position
    if (vsids.inHeap(var)) 
        vsids.update(var);
}
